//! `turn_budget`: the native program checked against the frozen raw of the ACTUAL original capture (139 rows: 39 command lines,
//! 100 API calls) in `data/turn_budget/original139.json` (generated by the dev-time extractor `gen_r49_goldens.py` from the saved
//! raw; only the private fixture roots are replaced by `<ROOT>` and `<FIX>`; nothing is guessed).
//!
//! * Command-line rows run as native **processes** of the built `turn_budget` (stdout, stderr and the first exit status compared
//!   byte for byte). Covered stream shapes: separate pipes and stdout on `/dev/full` (status 120). Not set up here (golden bytes
//!   are carried for the later gate): merged pipe (C16), pseudo-terminal (C17), closed descriptor 1 (C38).
//! * API rows run through the private bridge of the same binary (`TURN_BUDGET_BRIDGE`), so the typed transport (hexadecimal
//!   integers, bool before int, path-likes) is part of what is checked; the answer's class, `str()` and value are compared. The
//!   three rows whose answer is Python's own signature binding (`TypeError` for a missing/extra argument) are not business and are
//!   counted as such. The exception `args`/attributes are rebuilt by the Python adapter and are not asserted here.
//!
//! Source-written; compile and run are part of the later build window.

#[path = "common.rs"]
mod common;

use common::{data_path, dict, hex_decode, list, load_json_file, same, text_of};
use std::fs;
use std::io::Write;
use std::os::unix::fs::{symlink, PermissionsExt};
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};
use sweep_stop::pyvalue::{PyDict, PyValue};

const BIN: &str = env!("CARGO_BIN_EXE_turn_budget");
const OWNER_REL: &str = ".claude/skills/terraforming_node/scripts/turn_budget.py";
const SCHEMA_REL: &str = ".claude/schemas/agent-control-request.schema.json";

fn int_of(value: &PyValue) -> i64 {
    value.repr().parse().expect("an integer")
}

fn replace_all(haystack: &[u8], needle: &[u8], with: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(haystack.len());
    let mut at = 0;
    while at < haystack.len() {
        if haystack[at..].starts_with(needle) {
            out.extend_from_slice(with);
            at += needle.len();
        } else {
            out.push(haystack[at]);
            at += 1;
        }
    }
    out
}

fn untoken(bytes: &[u8], root: &Path, fix: &Path) -> Vec<u8> {
    let rooted = replace_all(bytes, b"<ROOT>", root.as_os_str().as_encoded_bytes());
    replace_all(&rooted, b"<FIX>", fix.as_os_str().as_encoded_bytes())
}

struct World {
    layouts: PathBuf,
    fix: PathBuf,
}

/// A fresh private tree holding the layouts and the schema fixtures of the capture.
fn materialize(data: &PyDict, tag: &str) -> World {
    let base = std::env::temp_dir().join(format!("turn_budget_{tag}_{}", std::process::id()));
    let _ = fs::remove_dir_all(&base);
    let (layouts, fix) = (base.join("layouts"), base.join("fix"));
    fs::create_dir_all(&layouts).expect("layouts dir");
    fs::create_dir_all(fix.join("schemas")).expect("fixtures dir");
    let mut links = Vec::new();
    for (name, spec) in dict(data.get("layouts").expect("layouts")).iter() {
        let name = name.to_utf8().expect("layout name");
        let spec = dict(spec);
        if let Some(target) = spec.get("symlink_to") {
            links.push((name, text_of(Some(target))));
            continue;
        }
        let root = layouts.join(&name);
        fs::create_dir_all(root.join(".claude/schemas")).expect("schemas dir");
        fs::create_dir_all(root.join(".claude/skills/terraforming_node/scripts"))
            .expect("scripts dir");
        if let Some(PyValue::Str(hex)) = spec.get("schema_hex") {
            let hex = hex.to_utf8().expect("hex");
            fs::write(root.join(SCHEMA_REL), hex_decode(&hex)).expect("schema");
        }
    }
    for (name, target) in links {
        symlink(layouts.join(target), layouts.join(name)).expect("layout symlink");
    }
    for (name, spec) in dict(data.get("schemas").expect("schemas")).iter() {
        let path = fix
            .join("schemas")
            .join(name.to_utf8().expect("fixture name"));
        let spec = dict(spec);
        if text_of(spec.get("kind")) == "dir" {
            fs::create_dir_all(&path).expect("fixture dir");
            continue;
        }
        fs::write(&path, hex_decode(&text_of(spec.get("hex")))).expect("fixture file");
        let mode = u32::from_str_radix(&text_of(spec.get("mode")), 8).expect("octal mode");
        fs::set_permissions(&path, fs::Permissions::from_mode(mode)).expect("mode");
    }
    World { layouts, fix }
}

fn golden() -> PyDict {
    match load_json_file(&data_path("turn_budget/original139.json")) {
        PyValue::Dict(data) => data,
        other => panic!("the golden file is not an object: {}", other.repr()),
    }
}

fn is_root() -> bool {
    rustix::process::geteuid().is_root()
}

#[test]
fn command_line_rows_match_the_saved_original_bytes() {
    let data = golden();
    let world = materialize(&data, "cli");
    let rows = list(data.get("cli").expect("cli rows").clone());
    assert_eq!(rows.len(), 39, "the capture has 39 command-line rows");
    let (mut compared, mut skipped, mut failures) = (0usize, Vec::new(), Vec::new());
    for row in &rows {
        let row = dict(row);
        let id = text_of(row.get("id"));
        let streams = text_of(row.get("streams"));
        if streams != "STREAMS_P1_SEPARATE_PIPES" && streams != "STREAMS_P4_STDOUT_DEV_FULL" {
            skipped.push(format!("{id} ({streams})"));
            continue;
        }
        if streams == "STREAMS_P4_STDOUT_DEV_FULL" && !dev_full_available() {
            skipped.push(format!(
                "{id} ({streams}: the sandbox denies opening /dev/full: NOT_RUN)"
            ));
            continue;
        }
        let root = world.layouts.join(text_of(row.get("layout")));
        let owner = root.join(OWNER_REL);
        let mut command = Command::new(BIN);
        command
            .args(
                list(row.get("argv").expect("argv").clone())
                    .iter()
                    .map(|a| text_of(Some(a))),
            )
            .env_clear()
            .current_dir(&root)
            .env("TURN_BUDGET_OWNER_PATH", &owner)
            .stdin(Stdio::null())
            .stderr(Stdio::piped());
        for (key, value) in dict(row.get("env").expect("env")).iter() {
            command.env(key.to_utf8().expect("env name"), text_of(Some(value)));
        }
        if streams == "STREAMS_P4_STDOUT_DEV_FULL" {
            let full = fs::OpenOptions::new()
                .write(true)
                .open("/dev/full")
                .expect("/dev/full");
            command.stdout(Stdio::from(full));
        } else {
            command.stdout(Stdio::piped());
        }
        let output = command
            .spawn()
            .expect("spawn")
            .wait_with_output()
            .expect("wait");
        let raw = dict(row.get("raw").expect("raw"));
        let expect = |name: &str| -> Vec<u8> {
            raw.get(name)
                .map(|hex| untoken(&hex_decode(&text_of(Some(hex))), &root, &world.fix))
                .unwrap_or_default()
        };
        let want_exit = int_of(row.get("exit").expect("exit")) as i32;
        if output.status.code() != Some(want_exit) {
            failures.push(format!(
                "{id}: exit {:?} != {want_exit}",
                output.status.code()
            ));
        }
        if streams == "STREAMS_P1_SEPARATE_PIPES" && output.stdout != expect("stdout.bin") {
            failures.push(format!(
                "{id}: stdout differs\n  got  {:?}\n  want {:?}",
                String::from_utf8_lossy(&output.stdout),
                String::from_utf8_lossy(&expect("stdout.bin"))
            ));
        }
        if output.stderr != expect("stderr.bin") {
            failures.push(format!(
                "{id}: stderr differs\n  got  {:?}\n  want {:?}",
                String::from_utf8_lossy(&output.stderr),
                String::from_utf8_lossy(&expect("stderr.bin"))
            ));
        }
        compared += 1;
    }
    let _ = fs::remove_dir_all(world.layouts.parent().expect("base"));
    assert!(
        failures.is_empty(),
        "{} of {compared} rows differ (skipped {skipped:?}):\n{}",
        failures.len(),
        failures.join("\n")
    );
    assert_eq!(compared + skipped.len(), 39);
}

fn c40_golden() -> PyDict {
    match load_json_file(&data_path("turn_budget/c40.json")) {
        PyValue::Dict(data) => data,
        other => panic!("the C40 golden is not an object: {}", other.repr()),
    }
}

#[test]
fn the_actual_c40_help_through_an_ascii_codec_matches_the_saved_original_bytes() {
    // R49C40: `--help` with PYTHONIOENCODING=ascii. The owner's UnicodeEncodeError at `file.write(message)` (one lone character,
    // position 173) below the argparse frames, first exit 1, nothing on stdout. Literal copy of the ONE actual capture.
    let world = materialize(&golden(), "c40");
    let data = c40_golden();
    let rows = list(data.get("cli").expect("cli rows").clone());
    assert_eq!(rows.len(), 1);
    let row = dict(&rows[0]);
    let root = world.layouts.join(text_of(row.get("layout")));
    let mut command = Command::new(BIN);
    command
        .args(
            list(row.get("argv").expect("argv").clone())
                .iter()
                .map(|a| text_of(Some(a))),
        )
        .env_clear()
        .current_dir(&root)
        .env("TURN_BUDGET_OWNER_PATH", root.join(OWNER_REL))
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());
    for (key, value) in dict(row.get("env").expect("env")).iter() {
        command.env(key.to_utf8().expect("env name"), text_of(Some(value)));
    }
    let output = command
        .spawn()
        .expect("spawn")
        .wait_with_output()
        .expect("wait");
    let raw = dict(row.get("raw").expect("raw"));
    let expect = |name: &str| untoken(&hex_decode(&text_of(raw.get(name))), &root, &world.fix);
    let _ = fs::remove_dir_all(world.layouts.parent().expect("base"));
    assert_eq!(
        output.status.code(),
        Some(int_of(row.get("exit").expect("exit")) as i32)
    );
    assert_eq!(output.stdout, expect("stdout.bin"));
    assert_eq!(
        String::from_utf8_lossy(&output.stderr),
        String::from_utf8_lossy(&expect("stderr.bin"))
    );
}

/// Whether this sandbox lets a test open `/dev/full` for writing (the rows that need it are NOT_RUN where it does not: nothing is substituted).
fn dev_full_available() -> bool {
    fs::OpenOptions::new().write(true).open("/dev/full").is_ok()
}

/// `cwd`: the process working directory of the row when it is not the layout root (R49S38 reads a relative path from the fixtures root).
fn bridge(world: &World, layout: &str, request: &str, cwd: Option<&Path>) -> PyValue {
    let root = world.layouts.join(layout);
    let mut child = Command::new(BIN)
        .env_clear()
        .env("LC_ALL", "C.UTF-8")
        .env("LANG", "C.UTF-8")
        .env("TURN_BUDGET_BRIDGE", "1")
        .env("TURN_BUDGET_OWNER_PATH", root.join(OWNER_REL))
        .current_dir(cwd.unwrap_or(&root))
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .expect("spawn bridge");
    child
        .stdin
        .take()
        .expect("stdin")
        .write_all(request.as_bytes())
        .expect("request");
    let output = child.wait_with_output().expect("wait");
    assert_eq!(
        output.status.code(),
        Some(0),
        "bridge failed: {}",
        String::from_utf8_lossy(&output.stderr)
    );
    sweep_stop::pyjson::loads_text(&sweep_stop::pystr::PyStr::from_surrogateescape(
        output.stdout.trim_ascii(),
    ))
    .expect("the answer is JSON")
}

#[test]
fn api_rows_match_the_saved_original_answers_through_the_bridge() {
    let data = golden();
    let world = materialize(&data, "api");
    let rows = list(data.get("api").expect("api rows").clone());
    assert_eq!(rows.len(), 100, "the capture has 100 API rows");
    let (mut compared, mut signature_rows, mut skipped, mut failures) =
        (0usize, 0usize, Vec::new(), Vec::new());
    let fix = world.fix.to_str().expect("utf-8 temp path").to_string();
    let fix_hex: String = fix.bytes().map(|b| format!("{b:02x}")).collect();
    for row in &rows {
        let row = dict(row);
        let id = text_of(row.get("id"));
        if matches!(row.get("python_signature"), Some(PyValue::Bool(true))) {
            signature_rows += 1;
            continue;
        }
        if id == "R49S33" && is_root() {
            skipped.push(format!("{id} (mode 000 is readable by root)"));
            continue;
        }
        let layout = text_of(row.get("layout"));
        let root = world.layouts.join(&layout);
        let default_schema = root.join(SCHEMA_REL).to_str().expect("utf-8").to_string();
        let mut request = match row.get("request").expect("request").clone() {
            PyValue::Dict(request) => request,
            other => panic!("{id}: request is not an object: {}", other.repr()),
        };
        let path_word = |text: &str| {
            let mut word = PyDict::new();
            word.set("t", PyValue::str("str"));
            word.set("v", PyValue::str(text));
            PyValue::Dict(word)
        };
        if matches!(request.get("path"), Some(PyValue::None)) {
            request.set("path", path_word(&default_schema));
        }
        if text_of(request.get("op")) == "declare" {
            request.set("default_schema", path_word(&default_schema));
        }
        request.set("protocol", PyValue::str("turn-budget-bridge/1"));
        let text = PyValue::Dict(request)
            .dumps_ascii()
            .expect("the request is JSON")
            .replace("$R49_FIXTURES", &fix)
            .replace("@FIXHEX@", &fix_hex);
        let answer = bridge(
            &world,
            &layout,
            &text,
            (id == "R49S38").then_some(world.fix.as_path()),
        );
        let answer = dict(&answer);
        let expect = dict(row.get("expect").expect("expect"));
        match text_of(expect.get("status")).as_str() {
            "returned" => {
                let ok = text_of(answer.get("status")) == "returned"
                    && same(
                        answer.get("value").expect("value"),
                        expect.get("value").expect("value"),
                    );
                if !ok {
                    failures.push(format!(
                        "{id}: wanted the value {}, got {}",
                        expect.get("value").expect("v").repr(),
                        PyValue::Dict(answer.clone()).repr()
                    ));
                }
            }
            _ => {
                let exc = answer.get("exc").map(dict);
                let want_message = String::from_utf8_lossy(&untoken(
                    text_of(expect.get("message")).as_bytes(),
                    &root,
                    &world.fix,
                ))
                .into_owned();
                let ok = text_of(answer.get("status")) == "raised"
                    && exc.is_some_and(|e| {
                        text_of(e.get("cls")) == text_of(expect.get("cls"))
                            && text_of(e.get("message")) == want_message
                    });
                if !ok {
                    failures.push(format!(
                        "{id}: wanted {}: {want_message}, got {}",
                        text_of(expect.get("cls")),
                        PyValue::Dict(answer.clone()).repr()
                    ));
                }
            }
        }
        compared += 1;
    }
    let _ = fs::remove_dir_all(world.layouts.parent().expect("base"));
    assert!(
        failures.is_empty(),
        "{} of {compared} rows differ:\n{}",
        failures.len(),
        failures.join("\n")
    );
    assert_eq!(compared + signature_rows + skipped.len(), 100);
    assert_eq!(
        signature_rows, 3,
        "three rows are Python's own signature errors"
    );
}

#[test]
fn a_run_without_its_owner_identity_fails_visibly_and_runs_nothing_else() {
    let output = Command::new(BIN)
        .env_clear()
        .arg("--caps")
        .output()
        .expect("spawn");
    assert_eq!(output.status.code(), Some(2));
    assert!(output.stdout.is_empty());
    assert!(String::from_utf8_lossy(&output.stderr).contains("TURN_BUDGET_OWNER_PATH"));
}

// ── contract fixes (R6 help codec, exit-120 codec name, R5 module facts, route events) ──────────────────────────────
// These four are NOT frozen-raw goldens: the ASCII-help traceback frames are derived from the argparse 3.12 source and the
// other points have no row in the frozen 139. They check the behaviour the source contract states; the proposed data-only row
// R49C40 (B49/extra-cli-original-proposal) is what a later capture would freeze for the help case.

fn run_cli(
    root: &Path,
    args: &[&str],
    env: &[(&str, &str)],
    observer: Option<&Path>,
    full: bool,
) -> std::process::Output {
    let mut command = Command::new(BIN);
    command
        .args(args)
        .env_clear()
        .current_dir(root)
        .env("LC_ALL", "C.UTF-8")
        .env("COLUMNS", "80")
        .env("TURN_BUDGET_OWNER_PATH", root.join(OWNER_REL))
        .stdin(Stdio::null())
        .stderr(Stdio::piped());
    for (key, value) in env {
        command.env(key, value);
    }
    if let Some(path) = observer {
        command.env("TURN_BUDGET_ROUTE_OBSERVER", path);
    }
    if full {
        command.stdout(Stdio::from(
            fs::OpenOptions::new()
                .write(true)
                .open("/dev/full")
                .expect("/dev/full"),
        ));
    } else {
        command.stdout(Stdio::piped());
    }
    command
        .spawn()
        .expect("spawn")
        .wait_with_output()
        .expect("wait")
}

#[test]
fn contract_fixes_codec_module_facts_and_route_events() {
    let data = golden();
    let world = materialize(&data, "fixes");
    let root = world.layouts.join("LAY_REAL");
    // R6: the help text through a codec that cannot spell it is the owner's UnicodeEncodeError with the argparse frames
    let help = run_cli(
        &root,
        &["--help"],
        &[("PYTHONIOENCODING", "ascii")],
        None,
        false,
    );
    let err = String::from_utf8_lossy(&help.stderr).into_owned();
    assert_eq!(help.status.code(), Some(1), "{err}");
    assert!(help.stdout.is_empty());
    assert!(
        err.starts_with("Traceback (most recent call last):\n"),
        "{err}"
    );
    assert!(
        err.contains("argparse.py\", line 2654, in _print_message\n    file.write(message)\n"),
        "{err}"
    );
    assert!(
        err.contains(
            "UnicodeEncodeError: 'ascii' codec can't encode character '\\ud134' in position "
        ),
        "{err}"
    );
    assert!(!err.contains("not reproduced"));
    // the exit-120 notice names the real codec (needs /dev/full: NOT_RUN where the sandbox denies it)
    if dev_full_available() {
        let full = run_cli(
            &root,
            &["--caps"],
            &[("PYTHONIOENCODING", "ascii")],
            None,
            true,
        );
        assert_eq!(full.status.code(), Some(120));
        assert!(String::from_utf8_lossy(&full.stderr).contains("encoding='ascii'"));
        let utf8 = run_cli(&root, &["--caps"], &[], None, true);
        assert!(String::from_utf8_lossy(&utf8.stderr).contains("encoding='utf-8'"));
    } else {
        eprintln!("NOT_RUN: the exit-120 notice needs /dev/full, which this sandbox denies");
    }
    // R5: the tripwire reads the module names the importer marshals; this program owns the list and the order
    let facts = run_cli(
        &root,
        &["--self-test"],
        &[("TURN_BUDGET_MODULE_NAMES", "REPO\nescalate\nGRADES")],
        None,
        false,
    );
    let first = String::from_utf8_lossy(&facts.stdout)
        .lines()
        .next()
        .unwrap_or("")
        .to_string();
    assert_eq!(
        first,
        "  [FAIL] 등급표·증액계수·정지한계가 되살아나지 않았다(발견 ['GRADES', 'escalate'])"
    );
    let plain = run_cli(&root, &["--self-test"], &[], None, false);
    assert!(String::from_utf8_lossy(&plain.stdout)
        .starts_with("  [PASS] 등급표·증액계수·정지한계가 되살아나지 않았다(발견 [])"));
    // route events: start before the business and end with the outcome, by the Rust process (its own pid and ppid)
    let observer = world.layouts.parent().expect("base").join("route.jsonl");
    let observed = run_cli(&root, &["--caps"], &[], Some(&observer), false);
    assert_eq!(observed.status.code(), Some(0));
    let lines: Vec<PyValue> = fs::read_to_string(&observer)
        .expect("observer file")
        .lines()
        .map(|line| sweep_stop::pyjson::loads(line).expect("event is JSON"))
        .collect();
    assert_eq!(lines.len(), 2);
    let (start, end) = (dict(&lines[0]), dict(&lines[1]));
    assert_eq!(text_of(start.get("event")), "start");
    assert_eq!(text_of(start.get("route")), "NativeCurrentSource");
    assert_eq!(text_of(start.get("shape")), "caps");
    assert_eq!(text_of(end.get("event")), "end");
    assert_eq!(text_of(end.get("outcome")), "exit:0");
    assert_eq!(
        int_of(start.get("pid").expect("pid")),
        int_of(end.get("pid").expect("pid"))
    );
    assert_eq!(
        int_of(start.get("ppid").expect("ppid")),
        i64::from(std::process::id())
    );
    assert_eq!(
        text_of(start.get("owner_path")),
        root.join(OWNER_REL).to_str().expect("utf-8")
    );
    // the private bridge records its calls the same way; a raised answer travels with transport exit 0
    let observer = world.layouts.parent().expect("base").join("bridge.jsonl");
    let mut child = Command::new(BIN)
        .env_clear()
        .env("LC_ALL", "C.UTF-8")
        .env("TURN_BUDGET_BRIDGE", "1")
        .env("TURN_BUDGET_ROUTE_OBSERVER", &observer)
        .env("TURN_BUDGET_OWNER_PATH", root.join(OWNER_REL))
        .current_dir(&root)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .expect("spawn bridge");
    let request = r#"{"protocol":"turn-budget-bridge/1","op":"declare","max_turns":{"t":"none"},"timeout_seconds":{"t":"none"},"source":{"t":"str","v":"s"},"caps":{"t":"dict","v":[[{"t":"str","v":"max_turns"},{"t":"int","hex":"+64"}],[{"t":"str","v":"timeout_seconds"},{"t":"int","hex":"+e10"}]]},"unit":{"t":"str","v":"native_turns"},"default_schema":{"t":"str","v":"/nonexistent"}}"#;
    child
        .stdin
        .take()
        .expect("stdin")
        .write_all(request.as_bytes())
        .expect("request");
    let output = child.wait_with_output().expect("wait");
    assert_eq!(output.status.code(), Some(0));
    let events = fs::read_to_string(&observer).expect("bridge observer");
    let ends: Vec<&str> = events.lines().collect();
    assert_eq!(ends.len(), 2);
    assert!(ends[0].contains("\"event\": \"start\"") || ends[0].contains("\"event\":\"start\""));
    assert!(ends[1].contains("raised:SystemExit"), "{}", ends[1]);
    let _ = fs::remove_dir_all(world.layouts.parent().expect("base"));
}
